<?php
namespace Modules\BankingMicrofinance\Http\Controllers;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\LoanReschedule;use Modules\BankingMicrofinance\Services\RescheduleService;
class RescheduleController extends Controller{public function index(){$items=LoanReschedule::latest()->paginate(25);return view('bankingmicrofinance::reschedules.index',compact('items'));}public function create(){return view('bankingmicrofinance::reschedules.form',['item'=>new LoanReschedule()]);}public function store(Request $request){LoanReschedule::create($request->all()+['requested_by'=>auth()->id()]);return redirect()->route('banking-microfinance.reschedules.index')->with('status','Reschedule request saved.');}public function edit(LoanReschedule $reschedule){return view('bankingmicrofinance::reschedules.form',['item'=>$reschedule]);}public function update(Request $request,LoanReschedule $reschedule){$reschedule->update($request->all());return redirect()->route('banking-microfinance.reschedules.index')->with('status','Reschedule updated.');}public function approve(LoanReschedule $reschedule,RescheduleService $service){$service->approve($reschedule,auth()->id());return back()->with('status','Reschedule approved.');}}
